package com.cortex.mobile;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.ImageFormat;
import android.graphics.SurfaceTexture;
import android.hardware.camera2.*;
import android.hardware.camera2.params.StreamConfigurationMap;
import android.media.Image;
import android.media.ImageReader;
import android.os.Bundle;
import android.os.Handler;
import android.os.HandlerThread;
import android.view.Gravity;
import android.view.Surface;
import android.view.TextureView;
import android.view.View;
import android.view.WindowManager;
import android.widget.FrameLayout;
import android.widget.TextView;
import java.nio.ByteBuffer;
import java.util.Arrays;

/** In-app Camera2 preview; frames never leave the device. */
public final class PairingScanActivity extends Activity {
    private TextureView preview;private TextView hint,torchButton;private HandlerThread thread;private Handler handler;private CameraDevice camera;private CameraCaptureSession session;private CaptureRequest.Builder requestBuilder;private ImageReader reader;private volatile boolean resumed,completed,opening;private volatile int cameraGeneration;private boolean torchEnabled;private volatile boolean torchAvailable;private long lastFrame;
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.BLACK);preview=new TextureView(this);root.addView(preview,new FrameLayout.LayoutParams(-1,-1));hint=new TextView(this);hint.setText("将电脑上的 Cortex 配对二维码放入画面");hint.setTextColor(Color.WHITE);hint.setTextSize(16);hint.setGravity(Gravity.CENTER);hint.setPadding(24,24,24,24);hint.setBackgroundColor(0xaa000000);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);root.addView(hint,hp);TextView close=new TextView(this);close.setText("✕");close.setTextSize(26);close.setTextColor(Color.WHITE);close.setGravity(Gravity.CENTER);close.setBackgroundColor(0x99000000);close.setContentDescription("关闭扫码");FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(dp(52),dp(52),Gravity.TOP|Gravity.END);root.addView(close,cp);close.setOnClickListener(v->finish());torchButton=new TextView(this);torchButton.setText("灯光");torchButton.setTextColor(Color.WHITE);torchButton.setGravity(Gravity.CENTER);torchButton.setBackgroundColor(0x99000000);torchButton.setContentDescription("打开补光灯");torchButton.setVisibility(View.GONE);FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(dp(64),dp(52),Gravity.TOP|Gravity.START);root.addView(torchButton,tp);torchButton.setOnClickListener(v->toggleTorch());root.setOnApplyWindowInsetsListener((v,insets)->{int top,bottom;if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());top=bars.top;bottom=bars.bottom;}else{top=insets.getSystemWindowInsetTop();bottom=insets.getSystemWindowInsetBottom();}FrameLayout.LayoutParams a=(FrameLayout.LayoutParams)close.getLayoutParams();a.topMargin=top;close.setLayoutParams(a);FrameLayout.LayoutParams t=(FrameLayout.LayoutParams)torchButton.getLayoutParams();t.topMargin=top;torchButton.setLayoutParams(t);FrameLayout.LayoutParams b=(FrameLayout.LayoutParams)hint.getLayoutParams();b.bottomMargin=bottom;hint.setLayoutParams(b);return insets;});setContentView(root);preview.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture s,int w,int h){open();}public void onSurfaceTextureSizeChanged(SurfaceTexture s,int w,int h){}public boolean onSurfaceTextureDestroyed(SurfaceTexture s){close();return true;}public void onSurfaceTextureUpdated(SurfaceTexture s){}});}
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override protected void onResume(){super.onResume();resumed=true;torchButton.setText("灯光");torchButton.setContentDescription("打开补光灯");torchButton.setVisibility(View.GONE);thread=new HandlerThread("cortex-qr-camera");thread.start();handler=new Handler(thread.getLooper());if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},71);else if(preview.isAvailable())open();}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==71){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED){if(resumed&&preview.isAvailable())open();}else hint.setText("需要相机权限才能扫码；可返回手动填写连接信息。");}}
    private void open(){if(!resumed||completed||opening||camera!=null||handler==null||!preview.isAvailable()||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;opening=true;final int generation=++cameraGeneration;try{CameraManager manager=(CameraManager)getSystemService(CAMERA_SERVICE);String id=null;for(String candidate:manager.getCameraIdList()){Integer facing=manager.getCameraCharacteristics(candidate).get(CameraCharacteristics.LENS_FACING);if(facing!=null&&facing==CameraCharacteristics.LENS_FACING_BACK){id=candidate;break;}}if(id==null)throw new IllegalStateException();CameraCharacteristics characteristics=manager.getCameraCharacteristics(id);torchAvailable=Boolean.TRUE.equals(characteristics.get(CameraCharacteristics.FLASH_INFO_AVAILABLE));int[] afModes=characteristics.get(CameraCharacteristics.CONTROL_AF_AVAILABLE_MODES);final boolean continuousAf=afModes!=null&&java.util.Arrays.stream(afModes).anyMatch(m->m==CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);runOnUiThread(()->{if(resumed&&generation==cameraGeneration)torchButton.setVisibility(torchAvailable?View.VISIBLE:View.GONE);});StreamConfigurationMap map=characteristics.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);android.util.Size[] sizes=map.getOutputSizes(ImageFormat.YUV_420_888);android.util.Size chosen=sizes[0];for(android.util.Size s:sizes)if(s.getWidth()<=1280&&s.getHeight()<=960 && Math.abs(s.getWidth()-640)+Math.abs(s.getHeight()-480)<Math.abs(chosen.getWidth()-640)+Math.abs(chosen.getHeight()-480))chosen=s;final int width=chosen.getWidth(),height=chosen.getHeight();reader=ImageReader.newInstance(width,height,ImageFormat.YUV_420_888,2);reader.setOnImageAvailableListener(this::frame,handler);manager.openCamera(id,new CameraDevice.StateCallback(){@Override public void onOpened(CameraDevice device){if(!resumed||completed||generation!=cameraGeneration){device.close();return;}opening=false;camera=device;if(!resumed||generation!=cameraGeneration){if(camera==device)camera=null;device.close();return;}try{SurfaceTexture texture=preview.getSurfaceTexture();if(texture==null){close();return;}texture.setDefaultBufferSize(width,height);Surface surface=new Surface(texture);device.createCaptureSession(Arrays.asList(surface,reader.getSurface()),new CameraCaptureSession.StateCallback(){@Override public void onConfigured(CameraCaptureSession configured){if(!resumed||camera==null||generation!=cameraGeneration){configured.close();return;}session=configured;if(!resumed||generation!=cameraGeneration){if(session==configured)session=null;configured.close();return;}try{CaptureRequest.Builder b=device.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);b.addTarget(surface);b.addTarget(reader.getSurface());if(continuousAf)b.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);requestBuilder=b;configured.setRepeatingRequest(b.build(),null,handler);}catch(Exception e){error();}}@Override public void onConfigureFailed(CameraCaptureSession configured){configured.close();error();}},handler);}catch(Exception e){error();}}@Override public void onDisconnected(CameraDevice device){device.close();if(generation==cameraGeneration){opening=false;if(camera==device)camera=null;error();}}@Override public void onError(CameraDevice device,int code){device.close();if(generation==cameraGeneration){opening=false;if(camera==device)camera=null;error();}}},handler);}catch(Exception e){opening=false;error();}}
    private void frame(ImageReader source){Image image=null;try{image=source.acquireLatestImage();if(image==null||completed||System.currentTimeMillis()-lastFrame<300)return;lastFrame=System.currentTimeMillis();Image.Plane p=image.getPlanes()[0];ByteBuffer b=p.getBuffer();int w=image.getWidth(),h=image.getHeight(),stride=p.getRowStride(),pixel=p.getPixelStride(),offset=b.position();byte[] y=new byte[w*h];for(int row=0;row<h;row++)for(int col=0;col<w;col++){int at=offset+row*stride+col*pixel;if(at>=b.limit())return;y[row*w+col]=b.get(at);}String decoded=QrLuminanceDecoder.decode(y,w,h);if(decoded==null)return;try{PairingPayload.parse(decoded);}catch(Exception invalid){runOnUiThread(()->hint.setText("二维码不是有效的 Cortex 配对码，请重新扫描。"));return;}completed=true;runOnUiThread(()->{Intent out=new Intent();out.putExtra("pairing",decoded);setResult(RESULT_OK,out);finish();});}catch(Exception ignored){}finally{if(image!=null)image.close();}}
    private void toggleTorch(){if(!torchAvailable||handler==null)return;handler.post(()->{try{if(session==null||requestBuilder==null)return;boolean next=!torchEnabled;requestBuilder.set(CaptureRequest.FLASH_MODE,next?CaptureRequest.FLASH_MODE_TORCH:CaptureRequest.FLASH_MODE_OFF);session.setRepeatingRequest(requestBuilder.build(),null,handler);torchEnabled=next;runOnUiThread(()->{torchButton.setText(next?"关闭灯光":"灯光");torchButton.setContentDescription(next?"关闭补光灯":"打开补光灯");});}catch(Exception e){runOnUiThread(()->hint.setText("无法开启补光灯，请改善环境光线。"));}});}
    private void error(){runOnUiThread(()->{if(resumed&&!isFinishing())hint.setText("无法启动相机，请返回并手动填写连接信息。");});}
    private void close(){cameraGeneration++;requestBuilder=null;torchEnabled=false;if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(reader!=null){reader.close();reader=null;}opening=false;}
    @Override protected void onPause(){resumed=false;close();if(thread!=null){thread.quitSafely();thread=null;handler=null;}super.onPause();}
}
